export type TPathItem = string | number

export const getDsPath = (lPath: TPathItem[]): string => {

	const results = []
	for (const x of lPath) {
		results.push((isString(x) ? `.${x}` : `[${x}]`))
	}
	const lParts = results
	return lParts.join('')
}

// ---------------------------------------------------------------------------

export const extract = (
		x: unknown,
		pathstr: string
		): unknown => {

	assert(defined(x), "extract(): x not defined")
	try {
		eval(`x = x${pathstr}`)
		return x
	}
	catch (err) {
		const msg: string = (
			  isString(err)          ? err
			: (err instanceof Error) ? err.message
			:                          'Unknown error'
			)
		reportExtractError(x, pathstr, msg)
		throw err
	}
}

// ---------------------------------------------------------------------------

export const getPathString = (
		dspath: string | TPathItem[]
		): string => {

	assert(nonEmpty(dspath), "Empty dspath")
	const pathstr = isArray(dspath) ? getDsPath(dspath) : dspath
	assert(nonEmpty(pathstr), "Empty pathstr")
	return pathstr
}

// ---------------------------------------------------------------------------

export const reportExtractError = (
		x: unknown,
		pathstr: string,
		errMsg: (string | undefined) = undef
		): void => {

	LOGVALUE(x, `ERROR EXTRACTING ${pathstr} FROM`, {ignoreEmptyKeys: true})
	if (defined(errMsg)) {
		ERR(errMsg)
	}
	return
}

